/// Replaces every element in `arr` that is strictly greater than `k` with -1.
/// Elements less than or equal to `k` remain unchanged.
fn replace(arr: &mut Vec<i32>, k: i32) {
    for x in arr.iter_mut() {
        if *x > k {
            *x = -1;
        }
    }
}

